import { h, Host } from "@stencil/core";
/**
 * @name SallaFulfillmentMethods
 * @description Displays product fulfillment options (pickup and delivery) as side-by-side cards.
 * Renders only the card(s) the product actually supports, per `supports_pickup` / `supports_delivery`
 * on the product-details response. Login Cycle, branch capabilities, and product-type eligibility are
 * all decided server-side (see `ProductFulfillmentMethods` composer) — this component is render-only
 * and must not re-check any of those rules on the front end.
 * @tag salla-fulfillment-methods
 */
export class SallaFulfillmentMethods {
    constructor() {
        this.methods = [];
        this.shouldRender = false;
        this.productId = null;
    }
    async componentWillLoad() {
        try {
            // page.id is server-injected, resolve it the same way salla-cashback-banner does
            // for this same hook slot (product:single.*).
            this.productId = this.host.dataset.productId || Salla.config.get('page.id');
            await Salla.onReady();
            await Salla.lang.onLoaded();
            if (!this.productId)
                return;
            const response = await Salla.product.getDetails(this.productId, []).catch(() => null);
            this.setLabels(response?.data ?? {});
        }
        catch (e) {
            Salla?.logger?.warn?.('salla-fulfillment-methods: init failed', e);
        }
    }
    setLabels(flags) {
        console.log('flags', flags);
        const methods = [];
        // Missing/undefined flags (BE not yet deployed, request failed) resolve to falsy → hidden.
        // Never fall back to showing both cards.
        if (flags?.supports_delivery) {
            methods.push({
                id: 'delivery',
                title: Salla.lang.getWithDefault('pages.products.promise_delivery_title', 'متاح للتوصيل'),
                subtitle: Salla.lang.getWithDefault('pages.products.promise_delivery_subtitle', 'طلبك يوصلك لباب البيت بسهولة.'),
                iconClass: 'sicon-location',
            });
        }
        if (flags?.supports_pickup) {
            methods.push({
                id: 'pickup',
                title: Salla.lang.getWithDefault('pages.products.promise_pickup_title', 'متاح للاستلام'),
                subtitle: Salla.lang.getWithDefault('pages.products.promise_pickup_subtitle', 'استلام فوري من أقرب فرع.'),
                iconClass: 'sicon-store',
            });
        }
        this.methods = methods;
        this.shouldRender = methods.length > 0;
    }
    render() {
        if (!this.shouldRender)
            return null;
        return (h(Host, { class: "s-fulfillment-methods" }, h("div", { class: "s-fulfillment-methods-list" }, this.methods.map(method => (h("div", { key: method.id, class: "s-fulfillment-methods-card" }, h("div", { class: "s-fulfillment-methods-content" }, h("div", { class: "s-fulfillment-methods-icon-wrap" }, h("i", { class: `${method.iconClass} s-fulfillment-methods-icon` })), h("div", { class: "s-fulfillment-methods-text" }, h("span", { class: "s-fulfillment-methods-title" }, method.title), h("span", { class: "s-fulfillment-methods-subtitle" }, method.subtitle)))))))));
    }
    static get is() { return "salla-fulfillment-methods"; }
    static get originalStyleUrls() {
        return {
            "$": ["salla-fulfillment-methods.scss"]
        };
    }
    static get styleUrls() {
        return {
            "$": ["salla-fulfillment-methods.css"]
        };
    }
    static get states() {
        return {
            "methods": {},
            "shouldRender": {}
        };
    }
    static get elementRef() { return "host"; }
}
